package lru

import "testing"

func TestBasic(t *testing.T) {
	c := New(2)
	c.Put(1, 10)
	c.Put(2, 20)
	if v, ok := c.Get(1); !ok || v != 10 {
		t.Errorf("Get(1) = %d,%v, want 10,true", v, ok)
	}
}

func TestEviction(t *testing.T) {
	c := New(2)
	c.Put(1, 1)
	c.Put(2, 2)
	c.Get(1)        // 1 is now most recent
	c.Put(3, 3)     // evicts 2 (LRU)
	if _, ok := c.Get(2); ok {
		t.Error("2 should have been evicted")
	}
	if v, ok := c.Get(1); !ok || v != 1 {
		t.Errorf("Get(1) = %d,%v, want 1,true", v, ok)
	}
	if v, ok := c.Get(3); !ok || v != 3 {
		t.Errorf("Get(3) = %d,%v, want 3,true", v, ok)
	}
}

func TestUpdate(t *testing.T) {
	c := New(2)
	c.Put(1, 1)
	c.Put(2, 2)
	c.Put(1, 10) // update 1 — should not evict 2
	if v, ok := c.Get(1); !ok || v != 10 {
		t.Errorf("Get(1) after update = %d,%v, want 10,true", v, ok)
	}
	if v, ok := c.Get(2); !ok || v != 2 {
		t.Errorf("Get(2) = %d,%v, want 2,true", v, ok)
	}
}

func TestMiss(t *testing.T) {
	c := New(1)
	if _, ok := c.Get(99); ok {
		t.Error("Get on empty cache should return false")
	}
}
